create table if not exists public.school_fee_definitions (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  name text not null,
  amount numeric(14,2) not null check (amount >= 0),
  currency text not null default 'XOF',
  active boolean not null default true,
  created_at timestamptz not null default now(),
  unique (school_id, name)
);
create table if not exists public.student_monthly_payment_statuses (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  student_id uuid not null references public.students(id) on delete cascade,
  fee_definition_id uuid references public.school_fee_definitions(id) on delete set null,
  billing_month date not null check (billing_month = date_trunc('month', billing_month)::date),
  amount_due numeric(14,2) not null default 0 check (amount_due >= 0),
  amount_paid numeric(14,2) not null default 0 check (amount_paid >= 0),
  status text not null default 'unpaid' check (status in ('paid','partial','unpaid','exempt')),
  recorded_by uuid references auth.users(id) on delete set null,
  recorded_at timestamptz,
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (student_id, fee_definition_id, billing_month)
);
create table if not exists public.student_access_cards (
  student_id uuid primary key references public.students(id) on delete cascade,
  school_id uuid not null references public.schools(id) on delete cascade,
  qr_token uuid not null default gen_random_uuid() unique,
  active boolean not null default true,
  issued_at timestamptz not null default now(),
  regenerated_at timestamptz
);
create index if not exists monthly_payment_school_month_idx on public.student_monthly_payment_statuses(school_id, billing_month);
create index if not exists monthly_payment_student_idx on public.student_monthly_payment_statuses(student_id, billing_month);
create index if not exists student_card_school_idx on public.student_access_cards(school_id);
alter table public.school_fee_definitions enable row level security;
alter table public.student_monthly_payment_statuses enable row level security;
alter table public.student_access_cards enable row level security;
create policy fee_definitions_read_member on public.school_fee_definitions for select to authenticated using (schooly_private.is_approved_school_member(school_id));
create policy fee_definitions_manage_payment_role on public.school_fee_definitions for all to authenticated using (schooly_private.has_school_permission(school_id, 'payments.manage')) with check (schooly_private.has_school_permission(school_id, 'payments.manage'));
create policy monthly_payments_read_member on public.student_monthly_payment_statuses for select to authenticated using (schooly_private.is_approved_school_member(school_id));
create policy monthly_payments_manage_payment_role on public.student_monthly_payment_statuses for all to authenticated using (schooly_private.has_school_permission(school_id, 'payments.manage')) with check (schooly_private.has_school_permission(school_id, 'payments.manage'));
create policy student_cards_read_payment_role on public.student_access_cards for select to authenticated using (schooly_private.has_school_permission(school_id, 'payments.view'));
create policy student_cards_manage_payment_role on public.student_access_cards for all to authenticated using (schooly_private.has_school_permission(school_id, 'payments.manage')) with check (schooly_private.has_school_permission(school_id, 'payments.manage'));

create or replace function public.lookup_student_payment_card(p_qr_token uuid) returns jsonb language plpgsql security definer set search_path = public as $$
declare card public.student_access_cards;
begin
  select * into card from public.student_access_cards where qr_token = p_qr_token and active = true;
  if card.student_id is null then raise exception 'Carte QR invalide'; end if;
  if not schooly_private.has_school_permission(card.school_id, 'payments.view') then raise exception 'Accès de paiement requis'; end if;
  return jsonb_build_object('student', (select jsonb_build_object('id', student.id, 'first_name', student.first_name, 'last_name', student.last_name, 'student_number', student.student_number) from public.students student where student.id = card.student_id), 'payments', coalesce((select jsonb_agg(jsonb_build_object('month', billing_month, 'status', status, 'amount_due', amount_due, 'amount_paid', amount_paid) order by billing_month desc) from public.student_monthly_payment_statuses where student_id = card.student_id), '[]'::jsonb));
end;
$$;
revoke all on function public.lookup_student_payment_card(uuid) from public;
grant execute on function public.lookup_student_payment_card(uuid) to authenticated;
